-- VYRA · Kacper Adamczyk: ZEROWANIE planu i nowy plan od czwartku 19.11.2026 do 6.06.2027.
-- Usuwa WSZYSTKIE przyszłe treningi (bieganie, siłownia, mobilność) z każdego planu, bez zapisanego wykonania,
-- i plan pod start ułożony w aplikacji. Potem wstawia jeden nowy plan. Zrobione treningi zostają.
-- 19.11 – 20.12: 5 biegów w tygodniu (Pn basen · Wt akcent + siłownia A · Śr easy · Czw Run Club + siłownia B · Pt wolne · Sob akcent · Nd long).
-- Od 21.12: plan na 6 dni. Próg na tętno 170-177 (Garmin: tętno progowe 179). Easy do ok. 155.
-- Można uruchomić kilka razy: zawsze zostaje jeden, aktualny plan.

do $$
declare
  v_ath   uuid;
  v_plan  record;
  v_s     uuid;
  v_ex    uuid;
  v_tpl   record;
  v_del   int;
  v_n     int := 0;
  v_g     int := 0;
  e       jsonb;
  r       record;
  ex      jsonb;
  st      jsonb;
  ex_pos  int;
  st_pos  int;
begin
  select id into v_ath from public.profiles
   where role = 'athlete' and lower(trim(full_name)) = lower('Kacper Adamczyk') order by created_at limit 1;
  if v_ath is null then raise exception 'Nie znaleziono konta zawodnika „Kacper Adamczyk”.'; end if;

  select * into v_plan from public.training_plans where athlete_id = v_ath and name = 'Plan biegowy 2026/27';
  if v_plan.id is null then raise exception 'Nie ma planu „Plan biegowy 2026/27”.'; end if;


  perform set_config('vyra.bulk', 'on', true);

  -- 1) Zerowanie: każdy przyszły trening zawodnika (z każdego planu i bez planu), bez zapisanego wykonania.
  delete from public.training_sessions s
   where s.athlete_id = v_ath and s.scheduled_date >= date '2026-11-19' and s.kind in ('running', 'strength', 'mobility')
     and s.status = 'planned'
     and not exists (select 1 from public.workout_executions x where x.session_id = s.id);
  get diagnostics v_del = row_count;
  -- Inne plany zawodnika kończą się dziś, żeby aplikacja pokazywała tylko ten jeden.
  update public.training_plans set end_date = date '2026-11-18'
   where athlete_id = v_ath and id <> v_plan.id and start_date <= date '2026-11-18'
     and (end_date is null or end_date > date '2026-11-18');
  -- Plan pod start ułożony w samej aplikacji (na telefonie): wyczyszczony, telefon przyjmie to przy następnym otwarciu.
  begin
    insert into public.app_state (user_id, key, value, ts, updated_at)
    values (v_ath, 'vyra-goal-plan', 'null'::jsonb, (extract(epoch from now()) * 1000)::bigint + 600000, now())
    on conflict (user_id, key) do update set value = 'null'::jsonb, ts = excluded.ts, updated_at = now();
  exception when undefined_table then null;
  end;

  -- 2) Miesiąc na 5 biegów w tygodniu, potem zwykły plan na 6 dni.
  for e in select * from jsonb_array_elements('[{"date": "2026-11-19", "cat": "easy", "km": 7, "title": "Run Club + przebieżki", "instr": "2 km easy + 4×100 m swobodnie szybko + Run Club 18:00 (ok. 5 km w tempie rozmowy)", "notes": "Plan na 5 dni · Tydzień przejściowy po zmęczeniu."}, {"date": "2026-11-21", "cat": "progression", "km": 10, "title": "Progresja 10 km", "instr": "10 km: 7 km easy, potem 3 km coraz szybciej, ostatni km ok. 4:15 (tętno do 165). Gotowość na zegarku słaba = całość easy.", "notes": "Plan na 5 dni · Tydzień przejściowy po zmęczeniu."}, {"date": "2026-11-22", "cat": "long", "km": 12, "title": "Długi bieg 12 km", "instr": "12 km easy, tempo rozmowy", "notes": "Plan na 5 dni · Tydzień przejściowy po zmęczeniu."}, {"date": "2026-11-24", "cat": "fartlek", "km": 10, "title": "Fartlek 8×1 min · siłownia A", "instr": "3 km + 8×(1 min żwawo RPE 7 / 1 min trucht) + 3 km · Siłownia A (lekko, 2×10)", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 1/4. Akcenty umiarkowane, mocniej od grudnia. Kołatanie, zawroty, ból w klatce = przerwij."}, {"date": "2026-11-25", "cat": "easy", "km": 10, "title": "Easy 10 km", "instr": "10 km easy + 6 przebieżek", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 1/4. Akcenty umiarkowane, mocniej od grudnia. Kołatanie, zawroty, ból w klatce = przerwij."}, {"date": "2026-11-26", "cat": "easy", "km": 8, "title": "Run Club + przebieżki · siłownia B", "instr": "3 km easy + 6×100 m swobodnie szybko + Run Club 18:00 (ok. 5 km w tempie rozmowy) · Siłownia B (lekko, bez skoków)", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 1/4. Akcenty umiarkowane, mocniej od grudnia. Kołatanie, zawroty, ból w klatce = przerwij."}, {"date": "2026-11-28", "cat": "threshold", "km": 11, "title": "6×2 min progowo", "instr": "3 km + 6×2 min (próg: tętno 170-177, ok. 3:55) / 2 min trucht + 3 km", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 1/4. Akcenty umiarkowane, mocniej od grudnia. Kołatanie, zawroty, ból w klatce = przerwij."}, {"date": "2026-11-29", "cat": "long", "km": 14, "title": "Długi bieg 14 km", "instr": "14 km easy, tempo rozmowy", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 1/4. Akcenty umiarkowane, mocniej od grudnia. Kołatanie, zawroty, ból w klatce = przerwij."}, {"date": "2026-12-01", "cat": "intervals", "km": 11, "title": "5×1000 m progowo · siłownia A", "instr": "3 km + 5×1000 m (próg: tętno 170-177, ok. 3:55), 1 min trucht + 2 km · Siłownia A (2×10)", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 2/4. Pierwsze 1000-ki progowe."}, {"date": "2026-12-02", "cat": "easy", "km": 11, "title": "Easy 11 km", "instr": "11 km easy + 6 przebieżek", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 2/4. Pierwsze 1000-ki progowe."}, {"date": "2026-12-03", "cat": "easy", "km": 8, "title": "Run Club + podbiegi · siłownia B", "instr": "3 km easy + 6×10 s pod górę (pełna przerwa) + Run Club 18:00 (ok. 5 km w tempie rozmowy) · Siłownia B (lekko)", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 2/4. Pierwsze 1000-ki progowe."}, {"date": "2026-12-05", "cat": "fartlek", "km": 10, "title": "Fartlek mieszany", "instr": "3 km + 8×(1 min w 3:40 + 20 s w 3:10), 90 s lekko między + 3 km", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 2/4. Pierwsze 1000-ki progowe."}, {"date": "2026-12-06", "cat": "long", "km": 16, "title": "Długi bieg 16 km", "instr": "16 km easy", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 2/4. Pierwsze 1000-ki progowe."}, {"date": "2026-12-08", "cat": "fartlek", "km": 12, "title": "Fartlek progowy · siłownia A", "instr": "3 km + 4×(5 min próg: tętno 170-177 + 1 min w 3:35), 1 min lekko między + 2 km · Siłownia A (3×8)", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 3/4. Dłuższe odcinki progowe."}, {"date": "2026-12-09", "cat": "easy", "km": 12, "title": "Easy 12 km", "instr": "12 km easy", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 3/4. Dłuższe odcinki progowe."}, {"date": "2026-12-10", "cat": "easy", "km": 9, "title": "Run Club + podbiegi · siłownia B", "instr": "3 km easy + 8×10 s pod górę (pełna przerwa) + Run Club 18:00 (ok. 5 km w tempie rozmowy) · Siłownia B", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 3/4. Dłuższe odcinki progowe."}, {"date": "2026-12-12", "cat": "fartlek", "km": 11, "title": "Fartlek mieszany", "instr": "3 km + 6×(2 min w 3:40 + 30 s w 3:05), 1 min lekko między + 2 km", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 3/4. Dłuższe odcinki progowe."}, {"date": "2026-12-13", "cat": "long", "km": 18, "title": "Długi bieg 18 km", "instr": "18 km easy", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 3/4. Dłuższe odcinki progowe."}, {"date": "2026-12-15", "cat": "threshold", "km": 14, "title": "3×3 km progowo · siłownia A", "instr": "3 km + 3×3 km (próg: tętno 170-177), 1 min trucht + 2 km · Siłownia A (3×6)", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 4/4. Ostatni tydzień na 5 dni. Test 3 km w sobotę: z wyniku przeliczamy tempa."}, {"date": "2026-12-16", "cat": "easy", "km": 12, "title": "Easy 12 km", "instr": "12 km easy", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 4/4. Ostatni tydzień na 5 dni. Test 3 km w sobotę: z wyniku przeliczamy tempa."}, {"date": "2026-12-17", "cat": "easy", "km": 9, "title": "Run Club + flying · siłownia B", "instr": "3 km easy + 4×60 m flying szybko (pełna przerwa) + Run Club 18:00 (ok. 5 km w tempie rozmowy) · Siłownia B", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 4/4. Ostatni tydzień na 5 dni. Test 3 km w sobotę: z wyniku przeliczamy tempa."}, {"date": "2026-12-19", "cat": "test", "km": 10, "title": "Test 3 km", "instr": "3 km rozgrzewki, 4 przebieżki, 3 km maksymalnie równo (bieżnia), 2 km schłodzenia. Wynik wpisz do aplikacji.", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 4/4. Ostatni tydzień na 5 dni. Test 3 km w sobotę: z wyniku przeliczamy tempa."}, {"date": "2026-12-20", "cat": "long", "km": 18, "title": "Długi bieg 18 km", "instr": "18 km easy", "notes": "Plan na 5 dni · Miesiąc na 5 dni, tydzień 4/4. Ostatni tydzień na 5 dni. Test 3 km w sobotę: z wyniku przeliczamy tempa."}, {"date": "2026-12-21", "cat": "easy", "km": 8, "title": "Easy 8 km + przebieżki", "instr": "8 km easy + 6 przebieżek 100 m", "notes": "Tydzień 9 planu. Dłuższe powtórzenia progowe, więcej podbiegów. Pierwszy tydzień znowu na 6 dni, więc poniedziałek krótszy."}, {"date": "2026-12-22", "cat": "intervals", "km": 15, "title": "3 km + 4×2,5 km w 3:52 (1 min trucht) + 2 km + siłownia A", "instr": "3 km + 4×2,5 km w 3:52 (tętno 170-177) (1 min trucht) + 2 km · Siłownia A (4×5)", "notes": "Tydzień 9 planu."}, {"date": "2026-12-23", "cat": "easy", "km": 13, "title": "Easy 13 km", "instr": "13 km easy", "notes": "Tydzień 9 planu."}, {"date": "2026-12-24", "cat": "intervals", "km": 10, "title": "Plyo + 6×200 m w 34-35 s (4 min przerwy) + easy + siłownia B", "instr": "plyo + 6×200 m w 34-35 s (4 min przerwy) + easy · Siłownia B", "notes": "Tydzień 9 planu."}, {"date": "2026-12-26", "cat": "intervals", "km": 10, "title": "Drabina", "instr": "Drabina: 3 km + 2×(200-400-600-400-200 m w 3:10), 200 m lekko między odcinkami, 4 min między seriami + 2 km", "notes": "Tydzień 9 planu."}, {"date": "2026-12-27", "cat": "long", "km": 20, "title": "Długi bieg 20 km", "instr": "20 km easy", "notes": "Tydzień 9 planu. Pierwszy long po miesiącu na 5 dni: 20 km zamiast 22."}, {"date": "2026-12-28", "cat": "easy", "km": 8, "title": "Easy 8 km + przebieżki", "instr": "8 km easy + 6 przebieżek", "notes": "Tydzień 10 planu. Tydzień lżejszy (święta). Dni przesuwaj swobodnie, ważne, żeby zostało 1 pełne wolne."}, {"date": "2026-12-29", "cat": "intervals", "km": 11, "title": "3 km + 5×1000 m w 3:55 (1 min trucht) + 2 km + siłownia A", "instr": "3 km + 5×1000 m w 3:55 (tętno 170-177) (1 min trucht) + 2 km · Siłownia A (lekko)", "notes": "Tydzień 10 planu."}, {"date": "2026-12-30", "cat": "easy", "km": 10, "title": "Easy 10 km", "instr": "10 km easy", "notes": "Tydzień 10 planu."}, {"date": "2026-12-31", "cat": "easy", "km": 8, "title": "Easy 8 km + szybkość + siłownia B", "instr": "8 km easy + 6×100 m · Siłownia B (lekko)", "notes": "Tydzień 10 planu."}, {"date": "2027-01-02", "cat": "easy", "km": 10, "title": "Easy 10 km + szybkość", "instr": "10 km easy + 6×20 s w 2:50 / 90 s lekko", "notes": "Tydzień 10 planu."}, {"date": "2027-01-03", "cat": "long", "km": 16, "title": "Długi bieg 16 km", "instr": "16 km easy", "notes": "Tydzień 10 planu."}, {"date": "2027-01-04", "cat": "easy", "km": 11, "title": "Easy 11 km + przebieżki", "instr": "11 km easy + 6 przebieżek", "notes": "Tydzień 11 planu. Pełny tydzień, piątek 1 stycznia jest wolny."}, {"date": "2027-01-05", "cat": "intervals", "km": 15, "title": "3 km + 5×2000 m w 3:50-3:53 (1 min trucht) + 2 km + siłownia A", "instr": "3 km + 5×2000 m w 3:50-3:53 (tętno 170-177) (1 min trucht) + 2 km · Siłownia A (ciężko, 4×5)", "notes": "Tydzień 11 planu."}, {"date": "2027-01-06", "cat": "easy", "km": 12, "title": "Easy 12 km", "instr": "12 km easy", "notes": "Tydzień 11 planu."}, {"date": "2027-01-07", "cat": "intervals", "km": 10, "title": "Plyo + 6×200 m w 34 s (4 min przerwy) + easy + siłownia B", "instr": "plyo + 6×200 m w 34 s (4 min przerwy) + easy · Siłownia B", "notes": "Tydzień 11 planu."}, {"date": "2027-01-09", "cat": "fartlek", "km": 12, "title": "Fartlek 3 temp", "instr": "Fartlek 3 temp: 3 km + 4×(3 min w 3:30 + 1 min w 3:10 + 30 s w 2:55), 2 min lekko między + 2 km", "notes": "Tydzień 11 planu."}, {"date": "2027-01-10", "cat": "long", "km": 22, "title": "Długi bieg 22 km", "instr": "22 km easy", "notes": "Tydzień 11 planu."}, {"date": "2027-01-11", "cat": "easy", "km": 11, "title": "Easy 11 km + przebieżki", "instr": "11 km easy + 6 przebieżek", "notes": "Tydzień 12 planu. Szczyt etapu B: najdłuższy bieg bazy."}, {"date": "2027-01-12", "cat": "fartlek", "km": 13, "title": "Fartlek progowy + siłownia A", "instr": "Fartlek progowy: 3 km + 4×(5 min w 3:50 (tętno 170-177) + 1 min w 3:30 + 1 min w 3:22), 1 min lekko mi