15-3:20/km) + 3 próby startu + 2 km", "notes": "Tydzień 28 planu. Tydzień finału (zakładam finał w czwartek 29 kwietnia; jeśli data jest inna, przesuń dni względem niej). Dwa wolne dni."}, {"date": "2027-05-05", "cat": "easy", "km": 4, "title": "Easy 4 km + przebieżki", "instr": "20 min easy + 4 przebieżki, obejrzenie trasy", "notes": "Tydzień 28 planu."}, {"date": "2027-05-06", "cat": "race", "km": 6, "title": "FINAŁ XC", "instr": "FINAŁ XC: 15-20 min rozgrzewki, 4 przebieżki, start", "notes": "Tydzień 28 planu."}, {"date": "2027-05-08", "cat": "easy", "km": 8, "title": "Easy 8 km", "instr": "8 km easy", "notes": "Tydzień 28 planu."}, {"date": "2027-05-09", "cat": "easy", "km": 12, "title": "Easy 12 km", "instr": "12 km easy", "notes": "Tydzień 28 planu."}, {"date": "2027-05-10", "cat": "easy", "km": 10, "title": "Easy 10 km + przebieżki", "instr": "10 km easy + 6 przebieżek", "notes": "Tydzień 29 planu. Powrót do progu po przełaju. Siłownia wraca do 2× w tygodniu. Jeśli w maju masz maturę, możesz obniżyć objętość o ok. 10%."}, {"date": "2027-05-11", "cat": "intervals", "km": 11, "title": "3 km + 5×1000 m w 3:50 (1 min trucht) + 2 km + siłownia A", "instr": "3 km + 5×1000 m w 3:50 (tętno 170-177) (1 min trucht) + 2 km · Siłownia A (3×6, umiarkowanie)", "notes": "Tydzień 29 planu."}, {"date": "2027-05-12", "cat": "easy", "km": 12, "title": "Easy 12 km", "instr": "12 km easy", "notes": "Tydzień 29 planu."}, {"date": "2027-05-13", "cat": "intervals", "km": 10, "title": "Plyo + 6×150 m w 23-24 s + easy + siłownia B", "instr": "plyo + 6×150 m w 23-24 s + easy · Siłownia B", "notes": "Tydzień 29 planu."}, {"date": "2027-05-15", "cat": "intervals", "km": 10, "title": "10 km w terenie + 8×(1 min w 3:30 + 15 s w 2:50), 90 s lekko, RPE 7", "instr": "10 km w terenie + 8×(1 min w 3:30 + 15 s w 2:50), 90 s lekko, RPE 7", "notes": "Tydzień 29 planu."}, {"date": "2027-05-16", "cat": "long", "km": 18, "title": "Długi bieg 18 km", "instr": "18 km easy", "notes": "Tydzień 29 planu."}, {"date": "2027-05-17", "cat": "easy", "km": 11, "title": "Easy 11 km + przebieżki", "instr": "11 km easy + 6 przebieżek", "notes": "Tydzień 30 planu. Budowa pod 10 km i półmaraton: sub-threshold + wydłużony long."}, {"date": "2027-05-18", "cat": "intervals", "km": 15, "title": "3 km + 5×2000 m w 3:50 (1 min trucht) + 2 km + siłownia A", "instr": "3 km + 5×2000 m w 3:50 (tętno 170-177) (1 min trucht) + 2 km · Siłownia A (3×5)", "notes": "Tydzień 30 planu."}, {"date": "2027-05-19", "cat": "easy", "km": 12, "title": "Easy 12 km", "instr": "12 km easy", "notes": "Tydzień 30 planu."}, {"date": "2027-05-20", "cat": "intervals", "km": 10, "title": "Plyo + 6×200 m w 34 s + easy + siłownia B", "instr": "plyo + 6×200 m w 34 s + easy · Siłownia B", "notes": "Tydzień 30 planu."}, {"date": "2027-05-22", "cat": "intervals", "km": 10, "title": "10 km w terenie + 6×(90 s w 3:25 + 30 s w 3:00), 90 s lekko, RPE 7", "instr": "10 km w terenie + 6×(90 s w 3:25 + 30 s w 3:00), 90 s lekko, RPE 7", "notes": "Tydzień 30 planu."}, {"date": "2027-05-23", "cat": "long", "km": 22, "title": "Długi bieg 22 km", "instr": "22 km easy, ostatnie 6 km w 4:05", "notes": "Tydzień 30 planu."}, {"date": "2027-05-24", "cat": "easy", "km": 11, "title": "Easy 11 km + przebieżki", "instr": "11 km easy + 6 przebieżek", "notes": "Tydzień 31 planu. Szczyt maja."}, {"date": "2027-05-25", "cat": "intervals", "km": 14, "title": "3 km + 3×3 km w 3:48-3:50 (1 min trucht) + 2 km + siłownia A", "instr": "3 km + 3×3 km w 3:48-3:50 (tętno 170-177) (1 min trucht) + 2 km · Siłownia A (3×5)", "notes": "Tydzień 31 planu."}, {"date": "2027-05-26", "cat": "easy", "km": 13, "title": "Easy 13 km", "instr": "13 km easy", "notes": "Tydzień 31 planu."}, {"date": "2027-05-27", "cat": "intervals", "km": 10, "title": "Plyo + 6×200 m w 33-34 s + easy + siłownia B", "instr": "plyo + 6×200 m w 33-34 s + easy · Siłownia B", "notes": "Tydzień 31 planu."}, {"date": "2027-05-29", "cat": "test", "km": 10, "title": "10 km easy + 8×(30 s w 3:05 / 90 s lekko) (szybkość przed 10 km kontrolnym)", "instr": "10 km easy + 8×(30 s w 3:05 / 90 s lekko) (szybkość przed 10 km kontrolnym)", "notes": "Tydzień 31 planu."}, {"date": "2027-05-30", "cat": "custom_run", "km": 24, "title": "24 km, ostatnie 8 km w 4:05", "instr": "24 km, ostatnie 8 km w 4:05", "notes": "Tydzień 31 planu."}, {"date": "2027-05-31", "cat": "easy", "km": 8, "title": "Easy 8 km + przebieżki", "instr": "8 km easy + 6 przebieżek", "notes": "Tydzień 32 planu. Tydzień lżejszy + 10 km kontrolny w niedzielę 30 maja (cel ok. 36:30). Wynik decyduje o terminie półmaratonu."}, {"date": "2027-06-01", "cat": "intervals", "km": 11, "title": "3 km + 5×1000 m w 3:48 (1 min trucht) + 2 km + siłownia A", "instr": "3 km + 5×1000 m w 3:48 (tętno 170-177) (1 min trucht) + 2 km · Siłownia A (lekko)", "notes": "Tydzień 32 planu."}, {"date": "2027-06-02", "cat": "easy", "km": 10, "title": "Easy 10 km", "instr": "10 km easy", "notes": "Tydzień 32 planu."}, {"date": "2027-06-03", "cat": "easy", "km": 8, "title": "Easy 8 km + szybkość + siłownia B", "instr": "8 km easy + 6×150 m (szybkość) · Siłownia B (lekko)", "notes": "Tydzień 32 planu."}, {"date": "2027-06-05", "cat": "easy", "km": 4, "title": "Easy 4 km + przebieżki", "instr": "20 min easy + 4 przebieżki", "notes": "Tydzień 32 planu."}, {"date": "2027-06-06", "cat": "test", "km": 14, "title": "10 km kontrolny", "instr": "10 km kontrolny: 2 km rozgrzewki, 10 km równo, 2 km schłodzenia", "notes": "Tydzień 32 planu."}]'::jsonb) loop
    -- dzień, w którym już jest zrobiony bieg, zostaje taki, jak był
    continue when exists (select 1 from public.training_sessions
                           where athlete_id = v_ath and kind = 'running' and scheduled_date = (e->>'date')::date);
    insert into public.training_sessions (coach_id, athlete_id, plan_id, kind, category, title, scheduled_date, instructions, notes)
    values (v_plan.coach_id, v_ath, v_plan.id, 'running', e->>'cat', e->>'title', (e->>'date')::date, e->>'instr', e->>'notes')
    returning id into v_s;
    insert into public.running_workouts (session_id, structure, planned_distance_m)
    values (v_s,
            case e->>'cat' when 'fartlek' then 'fartlek' when 'progression' then 'progression'
                           when 'intervals' then 'intervals' when 'threshold' then 'intervals' when 'hills' then 'intervals'
                           when 'race_pace' then 'intervals' else 'continuous' end,
            (e->>'km')::int * 1000);
    v_n := v_n + 1;
  end loop;

  -- 3) Siłownia A (wtorek) i B (czwartek) jako osobne treningi z szablonów.
  for r in
    select s.scheduled_date, (regexp_match(s.instructions, 'Siłownia ([AB])(?:\s*\(([^)]*)\))?')) as m
      from public.training_sessions s
     where s.plan_id = v_plan.id and s.kind = 'running' and s.scheduled_date >= date '2026-11-19'
       and s.instructions ~ 'Siłownia [AB]'
     order by s.scheduled_date
  loop
    select * into v_tpl from public.training_templates
     where name = case r.m[1] when 'A' then 'Siłownia A: nogi i siła' else 'Siłownia B: plyo i stabilizacja' end
     order by created_at limit 1;
    continue when v_tpl.id is null;
    continue when exists (select 1 from public.training_sessions
                           where athlete_id = v_ath and scheduled_date = r.scheduled_date and kind = 'strength' and template_id = v_tpl.id);
    insert into public.training_sessions (coach_id, athlete_id, plan_id, template_id, kind, category, title, scheduled_date,
                                          goal, instructions, notes, planned_duration_s)
    values (v_plan.coach_id, v_ath, v_plan.id, v_tpl.id, 'strength', v_tpl.category,
            v_tpl.payload->>'title' || coalesce(' (' || r.m[2] || ')', ''), r.scheduled_date,
            coalesce('Wskazówka z planu: ' || r.m[2] || '. ', '') || coalesce(v_tpl.payload->>'goal', ''),
            v_tpl.payload->>'instructions', 'Plan na 5 dni · Po bieganiu tego dnia (min. 3 godziny po akcencie).',
            nullif(v_tpl.payload->>'planned_duration_s', '')::int)
    returning id into v_s;
    for ex, ex_pos in select x, o::int from jsonb_array_elements(v_tpl.payload->'exercises') with ordinality as t(x, o) loop
      insert into public.strength_exercises (session_id, position, name, description, muscle_group, rest_s, tempo, notes)
      values (v_s, ex_pos, ex->>'name', ex->>'description', ex->>'muscle_group', nullif(ex->>'rest_s', '')::int, ex->>'tempo', ex->>'notes')
      returning id into v_ex;
      for st, st_pos in select x, o::int from jsonb_array_elements(ex->'sets') with ordinality as t(x, o) loop
        insert into public.strength_sets (exercise_id, position, planned_reps, planned_load_kg, planned_duration_s, planned_rpe, planned_rir)
        values (v_ex, st_pos, nullif(st->>'planned_reps', '')::int, nullif(st->>'planned_load_kg', '')::numeric,
                nullif(st->>'planned_duration_s', '')::int, nullif(st->>'planned_rpe', '')::numeric, nullif(st->>'planned_rir', '')::int);
      end loop;
    end loop;
    v_g := v_g + 1;
  end loop;

  perform set_config('vyra.bulk', '', true);
  perform public.notify(v_ath, 'session_assigned', 'Nowy plan od 19.11',
    v_n || ' biegów i ' || v_g || ' × siłownia · od 19.11, do 20.12 po 5 biegów w tygodniu', '/athlete/calendar', null);
  raise notice 'Wyzerowano % treningów, dodano % biegów i % treningów siłowych.', v_del, v_n, v_g;
end $$;
